/**
 * ADR-0100 sections 2 to 4 — the model manifest of Lakko's own translation
 * engine, and the pure rules over it.
 *
 * The manifest (`models.json`) is generated by `tools/translation-models` and
 * ships inside the web build. It lists the 19 language groups (one file each,
 * named by its SHA-256) and, per direction, where each model file sits inside
 * its group file with the hashes it must have. Nothing here fetches or stores;
 * the engine (`engine.ts`) and the downloader (`../../translation-models/`)
 * act on what these functions decide.
 */

/** One model file inside a group file. */
export interface ModelFile {
  readonly name: string;
  readonly offset: number;
  readonly length: number;
  /** SHA-256 of the zstd bytes, lower-case hex. */
  readonly sha256: string;
  /** SHA-256 of the decompressed file, lower-case hex. */
  readonly decompressedSha256: string;
  readonly decompressedBytes: number;
}

/** The file kinds a direction may carry. */
export type ModelFileKind = "model" | "lex" | "vocab" | "srcvocab" | "trgvocab";

export interface Direction {
  readonly group: number;
  readonly architecture: string;
  readonly version: string;
  readonly files: Partial<Record<ModelFileKind, ModelFile>>;
}

export interface Group {
  readonly id: number;
  readonly languages: readonly string[];
  /** SHA-256 of the group file, lower-case hex; also its name on the server. */
  readonly file: string;
  readonly bytes: number;
}

export interface Manifest {
  readonly format: 1;
  readonly groups: readonly Group[];
  /** Keyed `<source>-<target>` with Mozilla's language codes. */
  readonly directions: Readonly<Record<string, Direction>>;
}

const HEX64 = /^[0-9a-f]{64}$/;

function isInt(v: unknown): v is number {
  return typeof v === "number" && Number.isSafeInteger(v) && v >= 0;
}

function readFile(v: unknown): ModelFile | null {
  if (typeof v !== "object" || v === null) return null;
  const o = v as Record<string, unknown>;
  if (
    typeof o.name !== "string" ||
    !isInt(o.offset) ||
    !isInt(o.length) ||
    o.length === 0 ||
    typeof o.sha256 !== "string" ||
    !HEX64.test(o.sha256) ||
    typeof o.decompressedSha256 !== "string" ||
    !HEX64.test(o.decompressedSha256) ||
    !isInt(o.decompressedBytes) ||
    o.decompressedBytes === 0
  ) {
    return null;
  }
  return {
    name: o.name,
    offset: o.offset,
    length: o.length,
    sha256: o.sha256,
    decompressedSha256: o.decompressedSha256,
    decompressedBytes: o.decompressedBytes,
  };
}

const KINDS: readonly ModelFileKind[] = ["model", "lex", "vocab", "srcvocab", "trgvocab"];

/**
 * Read a manifest; `null` when anything in it is malformed. A direction whose
 * files fall outside its group file, or that lacks a model, a lexical
 * shortlist or a vocabulary, makes the whole manifest unreadable: the engine
 * then reports `unavailable` for every pair rather than guessing.
 */
export function readManifest(raw: unknown): Manifest | null {
  if (typeof raw !== "object" || raw === null) return null;
  const o = raw as Record<string, unknown>;
  if (o.format !== 1 || !Array.isArray(o.groups) || typeof o.directions !== "object" || o.directions === null) {
    return null;
  }
  const groups: Group[] = [];
  for (const g of o.groups) {
    if (typeof g !== "object" || g === null) return null;
    const r = g as Record<string, unknown>;
    if (
      !isInt(r.id) ||
      !Array.isArray(r.languages) ||
      r.languages.length === 0 ||
      !r.languages.every((l) => typeof l === "string" && l.length > 0) ||
      typeof r.file !== "string" ||
      !HEX64.test(r.file) ||
      !isInt(r.bytes) ||
      r.bytes === 0
    ) {
      return null;
    }
    if (groups.some((x) => x.id === r.id || x.file === r.file)) return null;
    groups.push({ id: r.id, languages: r.languages as string[], file: r.file, bytes: r.bytes });
  }
  const directions: Record<string, Direction> = {};
  for (const [key, d] of Object.entries(o.directions as Record<string, unknown>)) {
    if (typeof d !== "object" || d === null) return null;
    const r = d as Record<string, unknown>;
    const group = groups.find((g) => g.id === r.group);
    if (group === undefined || typeof r.files !== "object" || r.files === null) return null;
    const files: Partial<Record<ModelFileKind, ModelFile>> = {};
    for (const [kind, f] of Object.entries(r.files as Record<string, unknown>)) {
      if (!KINDS.includes(kind as ModelFileKind)) return null;
      const file = readFile(f);
      if (file === null || file.offset + file.length > group.bytes) return null;
      files[kind as ModelFileKind] = file;
    }
    const hasVocab = files.vocab !== undefined || (files.srcvocab !== undefined && files.trgvocab !== undefined);
    if (files.model === undefined || files.lex === undefined || !hasVocab) return null;
    directions[key] = {
      group: group.id,
      architecture: typeof r.architecture === "string" ? r.architecture : "",
      version: typeof r.version === "string" ? r.version : "",
      files,
    };
  }
  return { format: 1, groups, directions };
}

/**
 * The manifest's code for a language tag the rest of the client uses, or
 * `null` when the tag names nothing the manifest could hold.
 *
 * Chinese goes by script (`zh`, `zh-CN`, `zh-SG` -> Simplified; `zh-TW`,
 * `zh-HK`, `zh-MO` -> Traditional), Norwegian `no` / `nb` -> `nb` (Nynorsk is
 * not Bokmal and has no model), every Portuguese -> `pt`, the old codes
 * `iw` / `in` and Filipino `fil` -> `he` / `id` / `tl`; anything else keeps
 * its primary subtag.
 */
export function modelLanguage(tag: string): string | null {
  const parts = tag.trim().replace(/_/g, "-").split("-").filter((p) => p.length > 0);
  const primary = (parts[0] ?? "").toLowerCase();
  if (!/^[a-z]{2,3}$/.test(primary)) return null;
  const rest = parts.slice(1).map((p) => p.toLowerCase());
  if (primary === "zh") {
    if (rest.includes("hant") || rest.some((p) => p === "tw" || p === "hk" || p === "mo")) return "zh-Hant";
    return "zh-Hans";
  }
  if (primary === "nn") return null;
  if (primary === "no" || primary === "nb") return "nb";
  if (primary === "iw") return "he";
  if (primary === "in") return "id";
  if (primary === "fil") return "tl";
  return primary;
}

/**
 * The directions that translate `source` into `target`: the direct one when
 * the manifest has it, else through English (source -> en, en -> target).
 * Empty when the pair is the same language or cannot be made.
 */
export function routeFor(manifest: Manifest, source: string, target: string): string[] {
  const s = modelLanguage(source);
  const t = modelLanguage(target);
  if (s === null || t === null || s === t) return [];
  const direct = `${s}-${t}`;
  if (manifest.directions[direct] !== undefined) return [direct];
  if (s === "en" || t === "en") return [];
  const first = `${s}-en`;
  const second = `en-${t}`;
  return manifest.directions[first] !== undefined && manifest.directions[second] !== undefined ? [first, second] : [];
}

/** The groups a route needs, each once, in route order. */
export function groupsFor(manifest: Manifest, route: readonly string[]): Group[] {
  const out: Group[] = [];
  for (const key of route) {
    const d = manifest.directions[key];
    if (d === undefined) continue;
    const g = manifest.groups.find((x) => x.id === d.group);
    if (g !== undefined && !out.includes(g)) out.push(g);
  }
  return out;
}

/** The group a language belongs to, if any. */
export function groupOf(manifest: Manifest, language: string): Group | null {
  const l = modelLanguage(language);
  if (l === null) return null;
  return manifest.groups.find((g) => g.languages.includes(l)) ?? null;
}
